import{_ as a}from"./chunks/avg_query_time_comparison.tx9rCFYQ.js";import{_ as e,o as r,c as i,a4 as l}from"./chunks/framework.BaMAT_0D.js";const g=JSON.parse('{"title":"三种堆的Dijkstra：中文报告","description":"","frontmatter":{},"headers":[],"relativePath":"Lab/Advanced_Data_Structure/Project2_ShortestPath/report.md","filePath":"Lab/Advanced_Data_Structure/Project2_ShortestPath/report.md","lastUpdated":1793365822000}'),h={name:"Lab/Advanced_Data_Structure/Project2_ShortestPath/report.md"};function d(o,t,s,n,_,p){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="三种堆的dijkstra-中文报告" tabindex="-1">三种堆的Dijkstra：中文报告 <a class="header-anchor" href="#三种堆的dijkstra-中文报告" aria-label="Permalink to &quot;三种堆的Dijkstra：中文报告&quot;">​</a></h1><p>完整报告以LaTeX编写，正文与图表基于本次新实验。</p><ul><li><a href="./report_two_heap_history.html">原双堆报告归档</a></li></ul><h2 id="_1-问题与范围" tabindex="-1">1. 问题与范围 <a class="header-anchor" href="#_1-问题与范围" aria-label="Permalink to &quot;1. 问题与范围&quot;">​</a></h2><p>在同一套Dijkstra流程中比较BinaryHeap、DaryHeap4和FibonacciHeap。Simple作为小图参考。</p><h2 id="_2-设计" tabindex="-1">2. 设计 <a class="header-anchor" href="#_2-设计" aria-label="Permalink to &quot;2. 设计&quot;">​</a></h2><p>四叉堆使用外部dist数组和pos映射，降低树高，同时在下滤时比较最多四个孩子。固定d=4后与二叉堆同阶。</p><h2 id="_3-验证" tabindex="-1">3. 验证 <a class="header-anchor" href="#_3-验证" aria-label="Permalink to &quot;3. 验证&quot;">​</a></h2><p>9套原生测试、55项Python回归检查通过。四叉堆包含30,000次参考模型操作；330个随机图查询另外用Bellman-Ford核对。</p><h2 id="_4-本次实验" tabindex="-1">4. 本次实验 <a class="header-anchor" href="#_4-本次实验" aria-label="Permalink to &quot;4. 本次实验&quot;">​</a></h2><p>两组路网，各1000对查询、3轮、3种堆，共18,000次调用；算法块顺序逐轮轮换。</p><table tabindex="0"><thead><tr><th>数据集</th><th style="text-align:right;">二叉平均/ms</th><th style="text-align:right;">四叉平均/ms</th><th style="text-align:right;">斐波那契平均/ms</th><th style="text-align:right;">四叉相对二叉用时下降</th></tr></thead><tbody><tr><td>NY</td><td style="text-align:right;">46.64044</td><td style="text-align:right;">46.53342</td><td style="text-align:right;">89.52210</td><td style="text-align:right;">0.23%</td></tr><tr><td>BAY</td><td style="text-align:right;">48.86850</td><td style="text-align:right;">51.01878</td><td style="text-align:right;">106.78841</td><td style="text-align:right;">-4.40%</td></tr></tbody></table><p>正百分比表示用时下降，负值表示用时增加。</p><p><img src="'+a+'" alt="三种堆平均查询时间" loading="lazy"></p><h2 id="_5-讨论" tabindex="-1">5. 讨论 <a class="header-anchor" href="#_5-讨论" aria-label="Permalink to &quot;5. 讨论&quot;">​</a></h2><p>两张稀疏图上的三种理论上界都可化为O(V log V)。运行时间不能单独证明缓存或分配器开销的贡献。两组规模点也不足以证明渐近增长规律。</p><h2 id="_6-结论与历史记录" tabindex="-1">6. 结论与历史记录 <a class="header-anchor" href="#_6-结论与历史记录" aria-label="Permalink to &quot;6. 结论与历史记录&quot;">​</a></h2><p>结论以同一新批次的三种实现为依据。旧的results顶层与my_run数据保持不变，不与本次四叉堆拼接比较。详情、复现步骤与参考文献见中文PDF。</p>',18)])])}const m=e(h,[["render",d]]);export{g as __pageData,m as default};
